$(document).ready(function(){$("#menuToggle").on("click",function(){$("#mobileMenu").removeClass("-translate-x-full").addClass("translate-x-0")}),$("#menuClose").on("click",function(){$("#mobileMenu").removeClass("translate-x-0").addClass("-translate-x-full")});const l=$(".faq-item");l.length>0&&l.each(function(){const l=$(this).find(".faq-question");l.on("click",()=>{$(this).toggleClass("active")})}),$("#closeCallbackBtn").on("click",function(){$("#callbackModal").addClass("hidden")}),$("#callbackModal").on("click",function(l){l.target===this&&$(this).addClass("hidden")})});